class FindGoalEnv(MultiGridEnv):
    """
    Multi-room environment where agents must find and reach the green goal.
    Rooms are separated by walls with open gaps (no doors).
    Random wall obstacles are scattered inside rooms as visual/navigation clutter.
    """

    def __init__(
        self,
        size: int = 15,
        width: int = 30,
        height: int = 20,
        num_obstacles: int = 25,
        n_clutter: int = 10,
        randomize_goal: bool = True,
        max_steps: int = 250,
        joint_reward: bool = False,
        success_termination_mode: str = 'all',
        allow_agent_overlap: bool = False,
        see_through_walls: bool = True,
        min_goal_spawn_distance: int = 5,
        **kwargs
    ):
        self.num_obstacles = num_obstacles
        self.randomize_goal = randomize_goal
        self.n_clutter = n_clutter
        self.min_goal_spawn_distance = min_goal_spawn_distance
        self._goal_rng = np.random.default_rng()

        super().__init__(
            mission_space="get to the green goal square",
            grid_size= size,
            width=width,
            height=height,
            max_steps=max_steps,
            joint_reward=joint_reward,
            success_termination_mode=success_termination_mode,
            allow_agent_overlap=allow_agent_overlap,
            see_through_walls=see_through_walls,
            **kwargs,
        )

        # reinstantiate the agents to be NavigationAgents (different action space)
        agent_view_size = self.agents[0].view_size if isinstance(self.agents, Iterable) else 7
        self.agent_states = AgentState(self.num_agents) # joint agent state (vectorized)
        self.agents: list[NavigationAgent] = []
        for i in range(self.num_agents):
            agent = NavigationAgent(
                index=i,
                mission_space=self.mission_space,
                view_size=agent_view_size,
                see_through_walls=see_through_walls,
            )
            agent.state = self.agent_states[i]
            self.agents.append(agent)

        self._set_obs_spaces() # re-apply obs_mode shapes to the new agents

        # Action enumeration for this environment
        self.actions = NavigationAction

    def _gen_grid(self: MultiGridEnv, width, height):
        # 1. Create empty grid with surrounding walls
        self.grid = Grid(width, height)
        self.grid.wall_rect(0, 0, width, height)

        # Goal cell when the goal is not randomized (must not be covered by walls)
        fixed_goal = None if self.randomize_goal else (width - 2, height - 2)

        # 2. Scatter rectangular wall obstacles
        #    (rejecting any obstacle that would split the free space, so every
        #     free cell -- goal and agent spawns included -- stays reachable)
        obstacles_placed = 0
        max_attempts = 1000

        num_obstacles = int(self._variation('obstacles.number'))
        while obstacles_placed < num_obstacles and max_attempts > 0:
            max_attempts -= 1
            obs_w = self.np_random.integers(2, 5)
            obs_h = self.np_random.integers(1, 3)
            ox = self.np_random.integers(1, width  - obs_w - 1)
            oy = self.np_random.integers(1, height - obs_h - 1)

            cells = [(ox + dx, oy + dy) for dx in range(obs_w) for dy in range(obs_h)]
            conflict = any(self.grid.get(*cell) is not None for cell in cells)
            if conflict or fixed_goal in cells or not self._keeps_connected(cells):
                continue

            for dx in range(obs_w):
                for dy in range(obs_h):
                    self.grid.set(ox + dx, oy + dy, Wall(color=Color.grey))
            obstacles_placed += 1

        # 3. Place goal
        if self.randomize_goal:
            goal_pos = self.place_obj(
                Goal(),
                top=(1, 1),
                size=(width - 2, height - 2),
                max_tries=100,
            )
        else:
            goal_pos = np.asarray([width - 2, height - 2])
            self.put_obj(Goal(), width - 2, height - 2)
        self.goal_pos = goal_pos

        # 4. Extra single-cell clutter (also must not split the free space;
        #    best effort: stop when no valid cell is found in a dense grid)
        for _ in range(int(self._variation('clutter.number'))):
            try:
                self.place_obj(Wall(), top=(1, 1), size=(width - 2, height - 2), max_tries=100,
                               reject_fn=lambda env, pos: not env._keeps_connected([pos]))
            except RecursionError:
                break

        # 5. Place agents
        min_goal_spawn_distance = int(self._variation('goal.min_spawn_distance'))
        dist_to_goal = lambda pos: np.abs(np.asarray(pos) - goal_pos).sum()     # Manhattan distance
        for agent in self.agents:
            # a distance no free cell has (a small grid, or a sampled variation) would make the rejection
            # sampling below run forever: use the largest one available instead (no random draw used)
            occupied = {tuple(p) for p in np.asarray(self.agent_states.pos).reshape(-1, 2)}
            farthest = max((dist_to_goal((x, y)) for x in range(1, width - 1) for y in range(1, height - 1)
                            if self.grid.get(x, y) is None and (x, y) not in occupied), default=0)
            min_dist = min(min_goal_spawn_distance, farthest)
            if min_dist < min_goal_spawn_distance:
                warnings.warn(f"FindGoal: no free cell is {min_goal_spawn_distance} steps from the goal, agents "
                              f"spawn at least {min_dist} steps away instead", stacklevel=2)
            self.place_agent(agent, top=(1, 1), size=(width - 2, height - 2),
                             reject_fn=lambda env, pos, d=min_dist: dist_to_goal(pos) < d)

        return goal_pos

    def _keeps_connected(self, cells) -> bool:
        """
        Whether all free cells (empty or overlappable, e.g. the goal) remain
        4-connected if `cells` are turned into walls.
        """
        blocked = set(map(tuple, cells))
        free = {
            (x, y)
            for x in range(self.grid.width)
            for y in range(self.grid.height)
            if (x, y) not in blocked
            and ((obj := self.grid.get(x, y)) is None or obj.can_overlap())
        }
        if not free:
            return False

        # Flood fill from any free cell
        start = next(iter(free))
        seen, stack = {start}, [start]
        while stack:
            x, y = stack.pop()
            for nxt in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if nxt in free and nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        return len(seen) == len(free)

    def reset(self, seed=None, **kwargs):
        self._last_obs = {}   # clear frozen obs cache
        # Seed the goal RNG from the reset seed so layouts are fully reproducible.
        # [seed, 1] gives a stream independent of gym's np_random (seeded with `seed`).
        if seed is not None:
            self._goal_rng = np.random.default_rng([seed, 1])
        return super().reset(seed=seed, **kwargs)


