@patch
def gen_obs(self: FindGoalEnv) -> dict[AgentID, ObsType]:
    """
    Generate observations for each agent (partially observable, low-res encoding).

    Returns: Mapping from agent ID to observation dict, containing: * 'image': partially observable view of the environment * 'direction': agent's direction / orientation (acting as a compass) * 'position': agent's (x, y) cell in the grid * 'mission': textual mission string (instructions for the agent)
    """
    direction = self.agent_states.dir
    position = np.array(self.agent_states.pos)
    image = self._obs_encoding()
    rgb = self._obs_pixels()

    observations = {}
    for i in range(self.num_agents):
        if self.agent_states.terminated[i]:
            # Return last cached observation unchanged
            if hasattr(self, '_last_obs') and i in self._last_obs:
                observations[i] = self._last_obs[i]
                continue

        observations[i] = {
            'image':     image[i],
            'pixels':       rgb[i],
            'direction': direction[i],
            'position':  position[i],
            'mission':   self.agents[i].mission,
        }

    # Cache for next call
    if not hasattr(self, '_last_obs'):
        self._last_obs = {}
    for i in observations:
        self._last_obs[i] = observations[i]


    return observations



